    15→impl PolyCoeff {
    16→    /// Adds two polynomials `self + other` and returns the result.
    17→    ///
    18→    /// Polynomials may have different lengths; the shorter one is padded with zeros.
    19→    ///
    20→    /// WARNINGS:
    21→    /// - For `a + b - b` to be equal to `a`, the number of coefficients must be the same,
    22→    ///   otherwise we have an additional `Scalar::ZERO` in the result, but this is not a use
    23→    ///   case we should encounter in this crate.
    24→    #[must_use]
    25→    pub fn add(&self, other: &Self) -> Self {
    26→        let mut result = self.clone();
    27→        if other.len() > result.len() {
    28→            result.resize(other.len(), Scalar::ZERO);
    29→        }
    30→        for (i, &b) in other.iter().enumerate() {
    31→            result[i] += b;
    32→        }
    33→        result
    34→    }
    35→
    36→    /// Computes the additive inverse `-self` and returns the result.
    37→    #[must_use]
    38→    pub fn neg(&self) -> Self {
    39→        Self(self.iter().map(|c| -*c).collect())
    40→    }
    41→
    42→    /// Subtracts `other` from `self`, returning `self - other`.
    43→    ///
    44→    /// Internally implemented as `self + (-other)`.
    45→    ///
    46→    /// WARNINGS:
    47→    /// - For `a + b - b` to be equal to `a`, the number of coefficients must be the same,
    48→    ///   otherwise we have an additional `Scalar::ZERO` in the result, but this is not a use
    49→    ///   case we should encounter in this crate.
    50→    #[must_use]
    51→    pub fn sub(&self, other: &Self) -> Self {
    52→        self.add(&other.neg())
    53→    }
    54→
    55→    /// Evaluates the polynomial at the given scalar point `x`.
    56→    ///
    57→    /// Uses Horner’s method for efficient evaluation.
    58→    #[must_use]
    59→    pub fn eval(&self, x: &Scalar) -> Scalar {
    60→        let mut result = Scalar::ZERO;
    61→        for coeff in self.iter().rev() {
    62→            result = result * x + coeff;
    63→        }
    64→        result
    65→    }
    66→
    67→    /// Multiplies two polynomials `self * other` and returns the result.
    68→    ///
    69→    /// The result has degree `self.degree() + other.degree()`.
    70→    #[must_use]
    71→    pub fn mul(&self, other: &Self) -> Self {
    72→        let mut result = Self(vec![
    73→            Scalar::ZERO;
    74→            (self.len() + other.len()).saturating_sub(1)
